def clear(fig, titles=False):
    base.clear_figure_text(fig)
    for ax in fig.axes:
        if ax.get_legend() is not None:
            ax.get_legend().remove()
        if titles:
            ax.set_title('')


def key(fig,handles,labels,ncol=2,y=1,**kwargs):
    from matplotlib.legend_handler import HandlerTuple
    for handle in handles:
        if isinstance(handle,base.Line2D) and handle.get_linewidth()>1.3:
            handle.set_linewidth(1.8)
    return fig.legend(handles,labels,loc='upper center',bbox_to_anchor=(.53,y),
        ncol=ncol,frameon=False,fontsize=PT,handlelength=2.1,handletextpad=.55,
        columnspacing=1.1,labelspacing=.25,borderaxespad=.25,
        handler_map={tuple:HandlerTuple(ndivide=1)},**kwargs)


def linekey(fig,entries,ncol=4,y=1):
    return key(fig,[base.Line2D([],[],lw=1.8,**base.slides.style(role)) for label,role in entries],
               [label for label,role in entries],ncol=ncol,y=y)


def corekey(fig,markers=False):
    cases=base.plots.CORE
    labels=[r'Inclusive $R_{AA}$',r'$R_{AA}+\theta_g$',r'$R_{AA}+dR_{12}$',r'$R_{AA}+r_g$','All measurements']
    handles=[base.plots.handle(labels[i],base.plots.style(cases[i])) for i in range(5)]
    if markers:
        for handle,marker in zip(handles,['o','s','^','D','o']):
            handle.set_marker(marker)
            handle.set_markersize(3.7)
    key(fig,handles[:3],labels[:3],ncol=3)
    return key(fig,handles[3:],labels[3:],ncol=2,y=.945)


def style(fig):
    for ax in fig.axes:
        for spine in ax.spines.values():
            spine.set_linewidth(1.5)
        ax.tick_params(which='major',length=3.5,width=.9,pad=3)
        ax.tick_params(which='minor',length=2,width=.65)
        if getattr(ax,'_no_y_tick_marks',False):
            ax.tick_params(axis='y',which='both',length=0,right=False)
        for line in ax.lines:
            if line.get_linewidth()>1.3:
                line.set_linewidth(1.8)
            if line.get_marker() not in ('None',None,'',' '):
                line.set_markersize(min(line.get_markersize(),3.7))
        for collection in ax.collections:
            if isinstance(collection,mpl.contour.QuadContourSet):
                collection.set_linewidths([.9,1.8])
        ax.xaxis.labelpad=4
        ax.yaxis.labelpad=4
    base.typography(fig)


def panels(fig,height=3.10,top=.81,bottom=.19,right_label=True):
    fig.set_size_inches(WIDTH,height)
    fig.axes[0].set_position([.105,bottom,.365,top-bottom])
    fig.axes[1].set_position([.615 if right_label else .585,bottom,
                              .355 if right_label else .385,top-bottom])


def gallery_key(fig,aux=False):
    from matplotlib.patches import Patch
    color=base.plots.style('all')['color']
    prediction=(Patch(facecolor=color,alpha=.22),base.Line2D([],[],color=color,lw=1.8))
    handles=[base.Line2D([],[],color='#202326',marker='o',ms=3.7,lw=0),prediction]
    labels=['Data','Prediction (68%)']
    if aux:
        handles.extend([base.Line2D([],[],color='#777777',marker='o',mfc='white',ms=3.7,lw=0),
            (Patch(facecolor=color,alpha=.11),base.Line2D([],[],color=color,ls='--',lw=1.8))])
        labels.extend(['Unfitted data','Auxiliary'])
    key(fig,handles,labels,ncol=len(labels))


