def wake_bars(original,before):
    from matplotlib.patches import Patch
    fig,axes=plt.subplots(1,2,figsize=(WIDTH,3.15),sharey=True)
    roles=['default','blue','vermillion']
    original_values=[]
    for j,(source,ax) in enumerate(zip(original.axes,axes)):
        values=np.array([[bar.get_height() for bar in container] for container in source.containers])
        original_values.append(values.tolist())
        for i,(vv,role) in enumerate(zip(values,roles)):
            ypos=np.arange(2)+(i-1)*.23
            ax.barh(ypos,vv,height=.21,color=hp.comparison_style(role)['color'])
            for y,value in zip(ypos,vv):
                ax.text(value-.055,y,f'{value:.2f}',ha='right',va='center',color='white')
        ax.set(xlim=source.get_ylim(),ylim=(1.55,-.55),yticks=[0,1],
               yticklabels=['Positive wake','Subtracted wake'],
               xlabel=[r'$\langle p_T\rangle_E$ [GeV]',r'$\langle\Delta R_{\rm parton}\rangle_E$'][j])
        ax._no_y_tick_marks=True
        # Same numeric profiles; horizontal bars remove the rotated crowded labels.
        np.testing.assert_array_equal(values.ravel(),[p.get_width() for p in ax.patches])
    fig.subplots_adjust(left=.205,right=.955,top=.83,bottom=.22,wspace=.30)
    handles=[Patch(facecolor=hp.comparison_style(role)['color']) for role in roles]
    key(fig,handles,['Original','Requested shape','Conserved test'],ncol=3)
    after=base.signature(fig)
    save(fig,'preliminary_wake_implementation',after,dict(
        representation='Horizontal instead of vertical bars, identical numeric profiles',
        original_values=original_values,original_science=before))
    plt.close(original)

